package com.acme.auth.controller;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.view.RedirectView;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.net.URI;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.*;

@RestController
@RequestMapping("/oauth2")
public class OAuthCallbackController {

    @Value("${oauth.client-id}")
    private String clientId;

    @Value("${oauth.client-secret}")
    private String clientSecret;

    @Value("${oauth.allowed-redirect-hosts:app.acme.com,portal.acme.com}")
    private String allowedRedirectHosts;

    private final Map<String, String> stateToRedirect = Collections.synchronizedMap(new HashMap<>());
    private final SecureRandom random = new SecureRandom();

    @GetMapping("/authorize")
    public RedirectView authorize(
            @RequestParam("redirect_uri") String redirectUri,
            @RequestParam(value = "scope", defaultValue = "openid profile") String scope,
            HttpServletRequest request) {

        // Validate redirect_uri against allowed hosts
        String validated = validateRedirectUri(redirectUri);

        String state = generateState();
        stateToRedirect.put(state, validated);

        String authUrl = String.format(
            "https://idp.acme.com/authorize?client_id=%s&redirect_uri=%s&state=%s&scope=%s&response_type=code",
            clientId, validated, state, scope);

        return new RedirectView(authUrl);
    }

    @GetMapping("/callback")
    public RedirectView callback(
            @RequestParam("code") String code,
            @RequestParam("state") String state,
            HttpServletResponse response) {

        String redirectUri = stateToRedirect.remove(state);
        if (redirectUri == null) {
            return new RedirectView("/error?msg=invalid_state");
        }

        // Exchange code for token (simplified)
        String token = exchangeCodeForToken(code, redirectUri);

        // Redirect back to the client application with the token
        String finalRedirect = redirectUri + (redirectUri.contains("?") ? "&" : "?") + "token=" + token;
        return new RedirectView(finalRedirect);
    }

    private String validateRedirectUri(String redirectUri) {
        // Decode the URI to handle encoded characters
        String decoded = URLDecoder.decode(redirectUri, StandardCharsets.UTF_8);

        try {
            URI uri = new URI(decoded);
            String host = uri.getHost();

            // Check if the host ends with one of our allowed hosts
            String[] allowed = allowedRedirectHosts.split(",");
            for (String allowedHost : allowed) {
                if (host != null && host.endsWith(allowedHost.trim())) {
                    return decoded;
                }
            }
        } catch (Exception e) {
            // Fall through to throw
        }

        throw new IllegalArgumentException("Invalid redirect_uri: host not in allowlist");
    }

    private String generateState() {
        byte[] bytes = new byte[32];
        random.nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    private String exchangeCodeForToken(String code, String redirectUri) {
        // In production this calls the IDP token endpoint
        // Simplified: return a signed JWT
        return "eyJhbGciOiJSUzI1NiJ9." + Base64.getUrlEncoder().encodeToString(
            ("{'sub':'user','iat':" + System.currentTimeMillis()/1000 + "}").getBytes());
    }
}
